CONV = [(10, 5), (3, 2), (3, 2), (3, 2), (3, 2), (2, 2), (2, 2)]

TOTAL_STRIDE = 1
for _kernel, _stride in CONV:
    TOTAL_STRIDE *= _stride

BLANK = "_"


def out_len(n, kernel, stride):
    return (n - kernel) // stride + 1


def frames_for(num_samples):
    n = num_samples
    for kernel, stride in CONV:
        n = out_len(n, kernel, stride)
        if n <= 0:
            return 0
    return n


def frame_rate(sample_rate=16_000):
    return sample_rate / TOTAL_STRIDE


def frame_time(index, sample_rate=16_000):
    return index * TOTAL_STRIDE / sample_rate


def ctc_greedy_decode(tokens, blank=BLANK):
    out = []
    previous = None
    for token in tokens:
        if token != previous and token != blank:
            out.append(token)
        previous = token
    return "".join(out)


def ctc_segments(tokens, sample_rate=16_000, blank=BLANK):
    step = TOTAL_STRIDE / sample_rate
    segments = []
    previous = None
    for index, token in enumerate(tokens):
        if token == blank:
            previous = token
            continue
        if token != previous:
            segments.append({"token": token, "start": index * step,
                             "end": (index + 1) * step})
        else:
            segments[-1]["end"] = (index + 1) * step
        previous = token
    return segments
